8	// Pure billing rules (brief section 3). No imports, no I/O, and no use of the
9	// machine's timezone: calendar dates are handled as (year, month, day)
10	// integers and serial day numbers, and "today in Malaysia" is derived from
11	// the instant's epoch milliseconds plus a fixed UTC+8 offset.
12	
13	const MS_PER_DAY = 86_400_000;
14	const MALAYSIA_OFFSET_MS = 8 * 60 * 60 * 1000; // Asia/Kuala_Lumpur: UTC+8, no DST
15	const ISO_DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
16	const RINGGIT_PATTERN =
17	  /^([0-9]{1,3}(?:,[0-9]{3})+|[0-9]+)(?:\.([0-9]{1,2}))?$/;
18	
19	export type InvoiceKind = "deposit" | "rent";
20	
21	export interface ScheduledInvoice {
22	  kind: InvoiceKind;
23	  periodIndex: number | null; // 0, 1, 2... for rent; null for the deposit
24	  periodStart: string | null; // 'YYYY-MM-DD'; null for the deposit
25	  periodEnd: string | null; // 'YYYY-MM-DD', inclusive; null for the deposit
26	  dueDate: string; // 'YYYY-MM-DD'
27	  amountSen: number; // integer
28	}
29	
30	export type InvoiceStatus = "paid" | "partially_paid" | "unpaid" | "overdue";
31	
32	type CalendarDate = { year: number; month: number; day: number };
33	
34	type LeaseTerms = {
35	  startDate: string;
36	  endDate: string;
37	  monthlyRentSen: number;
38	  depositSen: number;
39	};
40	
41	type InvoiceAmounts = { dueDate: string; amountSen: number; paidSen: number };
42	
43	const isLeapYear = (year: number): boolean =>
44	  (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
45	
46	const daysInMonth = (year: number, month: number): number => {
47	  if (month === 2) {
48	    return isLeapYear(year) ? 29 : 28;
49	  }
50	  return [4, 6, 9, 11].includes(month) ? 30 : 31;
51	};
52	
53	const parseCalendarDate = (value: unknown, field: string): CalendarDate => {
54	  const match = typeof value === "string" ? ISO_DATE_PATTERN.exec(value) : null;
55	  if (!match) {
56	    throw new Error(`${field} must be a date written as YYYY-MM-DD`);
57	  }
58	  const year = Number(match[1]);
59	  const month = Number(match[2]);
60	  const day = Number(match[3]);
61	  if (
62	    year < 1 ||
63	    month < 1 ||
64	    month > 12 ||
65	    day < 1 ||
66	    day > daysInMonth(year, month)
67	  ) {
68	    throw new Error(`${field} is not a real calendar date: ${String(value)}`);
69	  }
70	  return { year, month, day };
71	};
72	
73	// Serial day number (days since 1970-01-01) of a proleptic Gregorian date.
74	// Howard Hinnant's days_from_civil: exact integer arithmetic, no Date object.
75	const toDayNumber = ({ year, month, day }: CalendarDate): number => {
76	  const y = month <= 2 ? year - 1 : year;
77	  const era = Math.floor(y / 400);
78	  const yearOfEra = y - era * 400;
79	  const dayOfYear =
80	    Math.floor((153 * (month + (month > 2 ? -3 : 9)) + 2) / 5) + day - 1;
81	  const dayOfEra =
82	    yearOfEra * 365 +
83	    Math.floor(yearOfEra / 4) -
84	    Math.floor(yearOfEra / 100) +
85	    dayOfYear;
86	  return era * 146_097 + dayOfEra - 719_468;
87	};
88	
89	// Inverse of toDayNumber (Hinnant's civil_from_days).
90	const fromDayNumber = (dayNumber: number): CalendarDate => {
91	  const z = dayNumber + 719_468;
92	  const era = Math.floor(z / 146_097);
93	  const dayOfEra = z - era * 146_097;
94	  const yearOfEra = Math.floor(
95	    (dayOfEra -
96	      Math.floor(dayOfEra / 1460) +
97	      Math.floor(dayOfEra / 36_524) -
98	      Math.floor(dayOfEra / 146_096)) /
99	      365,
100	  );
101	  const dayOfYear =
102	    dayOfEra -
103	    (365 * yearOfEra + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100));
104	  const mp = Math.floor((5 * dayOfYear + 2) / 153);
105	  const day = dayOfYear - Math.floor((153 * mp + 2) / 5) + 1;
106	  const month = mp < 10 ? mp + 3 : mp - 9;
107	  const year = yearOfEra + era * 400 + (month <= 2 ? 1 : 0);
108	  return { year, month, day };
109	};
110	
111	const formatCalendarDate = ({ year, month, day }: CalendarDate): string =>
112	  `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
113	
114	// Start date plus k calendar months, day clamped to the target month's length.
115	// Always counted from the start date, so Jan 31 -> Feb 28 -> Mar 31 (not Mar 28).
116	const addMonthsClamped = (
117	  start: CalendarDate,
118	  months: number,
119	): CalendarDate => {
120	  const monthIndex = start.month - 1 + months;
121	  const year = start.year + Math.floor(monthIndex / 12);
122	  const month = (monthIndex % 12) + 1;
123	  return { year, month, day: Math.min(start.day, daysInMonth(year, month)) };
124	};
125	
126	// monthlyRent * used / full, rounded half up, in exact integer arithmetic:
127	// floor((2 * rent * used + full) / (2 * full)). BigInt so no float ever appears.
128	const prorateHalfUp = (
129	  monthlyRentSen: number,
130	  daysUsed: number,
131	  daysInFullPeriod: number,
132	): number => {
133	  const numerator =
134	    2n * BigInt(monthlyRentSen) * BigInt(daysUsed) + BigInt(daysInFullPeriod);
135	  return Number(numerator / (2n * BigInt(daysInFullPeriod)));
136	};
137	
138	const assertSafeInteger = (
139	  value: unknown,
140	  field: string,
141	  minimum: number,
142	): number => {
143	  if (
144	    typeof value !== "number" ||
145	    !Number.isSafeInteger(value) ||
146	    value < minimum
147	  ) {
148	    throw new Error(
149	      `${field} must be an integer >= ${minimum}, got ${String(value)}`,
150	    );
151	  }
152	  return value;
153	};
154	
155	export const isCalendarDate = (value: unknown): value is string => {
156	  try {
157	    parseCalendarDate(value, "date");
158	    return true;
159	  } catch {
160	    return false;
161	  }
162	};
163	
164	// The calendar date in Malaysia (UTC+8, no DST) at a given instant, 'YYYY-MM-DD'.
165	export const malaysiaDateOf = (now: Date): string => {
166	  const time = now instanceof Date ? now.getTime() : Number.NaN;
167	  if (!Number.isFinite(time)) {
168	    throw new Error("now must be a valid Date");
169	  }
170	  return formatCalendarDate(
171	    fromDayNumber(Math.floor((time + MALAYSIA_OFFSET_MS) / MS_PER_DAY)),
172	  );
173	};
174	
175	export const generateSchedule = (lease: LeaseTerms): ScheduledInvoice[] => {
176	  const start = parseCalendarDate(lease.startDate, "startDate");
177	  const end = parseCalendarDate(lease.endDate, "endDate");
178	  const monthlyRentSen = assertSafeInteger(
179	    lease.monthlyRentSen,
180	    "monthlyRentSen",
181	    1,
182	  );
183	  const depositSen = assertSafeInteger(lease.depositSen, "depositSen", 0);
184	  const startDay = toDayNumber(start);
185	  const endDay = toDayNumber(end);
186	  if (endDay < startDay) {
187	    throw new Error("endDate must not be before startDate");
188	  }
189	
190	  const schedule: ScheduledInvoice[] = [];
191	  if (depositSen > 0) {
192	    schedule.push({
193	      kind: "deposit",
194	      periodIndex: null,
195	      periodStart: null,
196	      periodEnd: null,
197	      dueDate: lease.startDate,
198	      amountSen: depositSen,
199	    });
200	  }
201	
202	  for (let k = 0; ; k++) {
203	    const anchor = addMonthsClamped(start, k);
204	    const anchorDay = toDayNumber(anchor);
205	    if (anchorDay > endDay) {
206	      break;
207	    }
208	    const nextAnchorDay = toDayNumber(addMonthsClamped(start, k + 1));
209	    const fullEndDay = nextAnchorDay - 1;
210	    const periodEndDay = Math.min(fullEndDay, endDay);
211	    const amountSen =
212	      periodEndDay < fullEndDay
213	        ? prorateHalfUp(
214	            monthlyRentSen,
215	            periodEndDay - anchorDay + 1,
216	            nextAnchorDay - anchorDay,
217	          )
218	        : monthlyRentSen;
219	    const periodStart = formatCalendarDate(anchor);
220	    schedule.push({
221	      kind: "rent",
222	      periodIndex: k,
223	      periodStart,
224	      periodEnd: formatCalendarDate(fromDayNumber(periodEndDay)),
225	      dueDate: periodStart,
226	      amountSen,
227	    });
228	  }
229	  return schedule;
230	};
231	
232	export const invoiceStatus = (
233	  invoice: InvoiceAmounts,
234	  now: Date,
235	): InvoiceStatus => {
236	  const due = parseCalendarDate(invoice.dueDate, "dueDate");
237	  const amountSen = assertSafeInteger(invoice.amountSen, "amountSen", 0);
238	  const paidSen = assertSafeInteger(invoice.paidSen, "paidSen", 0);
239	  const today = parseCalendarDate(malaysiaDateOf(now), "today");
240	  if (paidSen >= amountSen) {
241	    return "paid";
242	  }
243	  if (toDayNumber(today) > toDayNumber(due)) {
244	    return "overdue";
245	  }
246	  if (paidSen > 0) {
247	    return "partially_paid";
248	  }
249	  return "unpaid";
250	};
251	
252	export const parseRinggitToSen = (input: string): number => {
253	  const match =
254	    typeof input === "string" ? RINGGIT_PATTERN.exec(input.trim()) : null;
255	  if (!match || match[1] === undefined) {
256	    throw new Error(`Not a valid ringgit amount: ${JSON.stringify(input)}`);
257	  }
258	  // Built from the digit strings, never via parseFloat: "1.15" must be 115, not 114.99...
259	  const ringgit = BigInt(match[1].replaceAll(",", ""));
260	  const sen = BigInt((match[2] ?? "").padEnd(2, "0"));
261	  const total = ringgit * 100n + sen;
262	  if (total > BigInt(Number.MAX_SAFE_INTEGER)) {
263	    throw new Error(`Amount is too large: ${JSON.stringify(input)}`);
264	  }
265	  return Number(total);
266	};
