488	// Integer money helpers. Amounts are always integer sen (1 RM = 100 sen);
489	// floats never touch money. Rounding lives in exactly one place:
490	// prorateHalfUp in billing.ts (the only place a fraction of a sen is created).
491	
492	export { parseRinggitToSen } from "./billing";
493	
494	const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);
495	const MIN_SAFE = BigInt(Number.MIN_SAFE_INTEGER);
496	
497	const toSenBigInt = (sen: number | bigint): bigint => {
498	  if (typeof sen === "bigint") {
499	    return sen;
500	  }
501	  if (!Number.isSafeInteger(sen)) {
502	    throw new Error(`Amount in sen must be a safe integer, got ${String(sen)}`);
503	  }
504	  return BigInt(sen);
505	};
506	
507	/**
508	 * 150050 -> 'RM 1,500.50', -500 -> '-RM 5.00'. Built from integer division
509	 * instead of Intl.NumberFormat so the text is byte-identical on every
510	 * runtime/ICU build (no NBSP surprises, no hydration mismatch).
511	 */
512	export const formatSen = (sen: number | bigint): string => {
513	  const value = toSenBigInt(sen);
514	  const negative = value < 0n;
515	  const absolute = negative ? -value : value;
516	  const ringgit = (absolute / 100n)
517	    .toString()
518	    .replace(/\B(?=(\d{3})+(?!\d))/g, ",");
519	  const cents = (absolute % 100n).toString().padStart(2, "0");
520	  return `${negative ? "-" : ""}RM ${ringgit}.${cents}`;
521	};
522	
523	/** 150050 -> '1500.50': a sen amount as the plain text a money input accepts. */
524	export const senToInputValue = (sen: number | bigint): string =>
525	  formatSen(sen).replace("RM ", "").replaceAll(",", "");
526	
527	/** Prisma returns bigint for `bigint` columns; JSON needs a number. Throws instead of losing precision. */
528	export const toSafeNumber = (value: bigint): number => {
529	  if (typeof value !== "bigint") {
530	    throw new Error(`Expected a bigint, got ${typeof value}`);
531	  }
532	  if (value > MAX_SAFE || value < MIN_SAFE) {
533	    throw new Error(
534	      `Value ${value.toString()} is outside the safe integer range`,
535	    );
536	  }
537	  return Number(value);
538	};
